void crc64_ecma_step32b_model(const uint32_t in[10], uint32_t out[10]) {
    uint64_t crc = ((uint64_t)in[1] << 32) | in[0];
    for (int i = 0; i < 8; i++) {
        uint32_t w = in[2 + i];
        for (int k = 0; k < 4; k++) {
            uint8_t b = (w >> (k * 8)) & 0xFF;
            crc ^= ((uint64_t)b << 56);
            for (int j = 0; j < 8; j++) {
                uint64_t mask = (uint64_t)0 - ((crc >> 63) & 1);
                crc = (crc << 1) ^ (0x42F0E1EBA9EA3693ull & mask);
            }
        }
    }
    out[0] = (uint32_t)crc;
    out[1] = (uint32_t)(crc >> 32);
    for (int i = 2; i < 10; i++) {
        out[i] = 0;
    }
}

